// halo3 - the run-time shader translator (see halo3_traductor.h).
//
// XenosRecomp is built into this one file with the defines of its GLSL mode: the translator's class layout depends on
// them, so nothing else includes shader_recompiler.h.
#define NFSMW_RECOMP 1
#define HALO3_RECOMP 1
#define XENOS_GLSL 1
#include "../../shaders/pch_min.h"
#include "../../shaders/XenosRecomp/shader_recompiler.cpp"

#include "halo3_traductor.h"
#include "halo3_traductor_nucleo.h"

#include "halo3_preludio_glsl.h"  // generated by CMake from shaders/XenosRecomp/shader_common.glsl: kPreludioGlsl

#include <rex/ui/deko3d/glsl.h>

#include <exception>
#include <string_view>

namespace halo3 {

bool TraducirMicrocodigo(bool vertices, std::span<const uint32_t> microcodigo, rex::x360::EntradaShader& e,
                         std::string& error) {
  if (microcodigo.empty() || microcodigo.size() > 0x10000) {
    error = "microcodigo vacio o demasiado largo";
    return false;
  }
  std::string texto;
  uint32_t salidas = 0;
  try {
    texto = nucleo::Traducir(vertices, microcodigo, kPreludioGlsl, salidas);
  } catch (const std::exception& excepcion) {
    error = excepcion.what();
    return false;
  }
  const std::string_view cuerpo = nucleo::Cuerpo(texto);
  if (cuerpo.empty()) {
    error = "la traduccion no tiene main";
    return false;
  }

  const rex::deko3d::GlslDeko g = rex::deko3d::GlslDeTraductor(texto, vertices, 0);
  if (!g.error.empty()) {
    error = g.error;
    return false;
  }
  e.vertices = vertices;
  e.microcodigo.assign(microcodigo.begin(), microcodigo.end());
  e.huella = XXH3_64bits(microcodigo.data(), microcodigo.size_bytes());
  e.huella_contenedor = 0;
  e.elementos.clear();
  e.samplers.clear();
  for (uint32_t b = 0; b < rex::deko3d::kMaxTexturas; ++b) {
    if (!((g.texturas >> b) & 1)) continue;
    rex::x360::SamplerShader s;
    s.registro = uint16_t(b);
    s.tipo = ((g.texturas_3d >> b) & 1) ? 13 : ((g.texturas_cubo >> b) & 1) ? 14 : 12;  // D3DXPARAMETER_TYPE
    e.samplers.push_back(s);
  }
  e.salidas = salidas;
  e.descarta = cuerpo.find("clip(") != std::string_view::npos || cuerpo.find("discard") != std::string_view::npos;
  e.constantes_bytes = 256 * 16;
  e.ubicaciones_por_orden = true;
  e.glsl = std::move(texto);
  return true;
}

}  // namespace halo3
